#define XLAT12_ABI_PTR_ROWS (sizeof kXlat12AbiPtrs / sizeof kXlat12AbiPtrs[0])

/* 0.0.391 — THE ROW FOR A PROGRAM IDENTITY **AT A NAMED STAGE**, or NULL; NULL means UNKNOWN,
 * never "declares no pointers".
 *
 * WHY THE STAGE IS NOW PART OF THE KEY. Through 0.0.390 the only lookup was by (ndw, fnv), and its ONE non-test caller
 * passed a FRAGMENT identity (xlat12_ib.c's kDTableAbi rows) - so the three vertex rows below were reachable by nothing
 * and checked by nothing: the adversarial review of 0.0.390 found them dead data. They are wired now
 * (d_table_desc gathers the vertex stage's declared pointers beside the fragment's), and a stage-keyed lookup is what
 * makes it impossible for one stage's row to be served to the other if two programs ever collide on (ndw, fnv). */
static inline const xlat12_abi_ptrs *xlat12_abi_ptr_row_stage(uint32_t ndw, uint32_t fnv, uint32_t stage)
{
    for (uint32_t i = 0; i < XLAT12_ABI_PTR_ROWS; i++)
        if (kXlat12AbiPtrs[i].ndw == ndw && kXlat12AbiPtrs[i].fnv == fnv && kXlat12AbiPtrs[i].stage == stage)
            return &kXlat12AbiPtrs[i];
    return 0;
}

/* The FRAGMENT row for an identity, or NULL. 0.0.390's spelling, now stage-keyed: every caller it ever had passed a
 * fragment identity, so this is a tightening and not a change of behaviour for any of them. */
static inline const xlat12_abi_ptrs *xlat12_abi_ptr_row(uint32_t ndw, uint32_t fnv)
{
    return xlat12_abi_ptr_row_stage(ndw, fnv, 0u);
}

/* build 0.0.470 (an internal design note section 2, "the latent silent truncation"): THE ONE PLACE A
 * ROW'S POINTER COUNT IS READ. Returns how many of `ap`'s pointers a reader may walk (min(nptr, XLAT12_ABI_PTR_MAX))
 * and, when the row declares MORE than that, sets `*over` to 1 - the reader's list is then incomplete, which every
 * consumer of xlat12_draw_stats.in_over already refuses on. Through 0.0.455 every loop read `q < ap->nptr && q <
 * XLAT12_ABI_PTR_MAX` and a longer row simply lost its tail with nothing set. `ap` NULL returns 0 and leaves *over
 * alone (no row is UNKNOWN, a separate fact the callers already carry as in_ptr_known / in_vptr_known). */
static inline uint32_t xlat12_abi_ptr_n(const xlat12_abi_ptrs *ap, uint32_t *over)
{
    if (!ap) return 0u;
    if (ap->nptr > XLAT12_ABI_PTR_MAX) { if (over) *over = 1u; return XLAT12_ABI_PTR_MAX; }
    return ap->nptr;
}

